// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 callCount) public {
        vm.assume(callCount > 0 && callCount <= 100);
        address sender = address(0x12345);
        vm.deal(sender, callCount * 1 ether);
        vm.startPrank(sender);
        for (uint256 i = 0; i < callCount; i++) {
            (bool ok,) = address(c).call{value: 1 ether}("");
            require(ok, "receive failed");
        }
        vm.stopPrank();
        assertTrue(c.depositsCount() == callCount);
    }
}
